// Single-file bundle of supabase/functions/payment-init (generated by npm run bundle:functions). Paste into the dashboard editor.

import { createClient } from "npm:@supabase/supabase-js@2";
import { constants, createHash, createPrivateKey, createPublicKey, createSign, privateDecrypt, publicEncrypt } from "node:crypto";
import { Buffer } from "node:buffer";

// supabase/functions/_shared/gateways.ts
const asObj = (v) => v && typeof v === "object" ? v : {};
const sslBase = (mode) => mode === "live" ? "https://securepay.sslcommerz.com" : "https://sandbox.sslcommerz.com";
async function sslInit(f, c, txn, urls, cust) {
	const body = new URLSearchParams({
		store_id: c.storeId,
		store_passwd: c.storePasswd,
		total_amount: Number(txn.amount).toFixed(2),
		currency: "BDT",
		tran_id: txn.id,
		success_url: urls.success,
		fail_url: urls.fail,
		cancel_url: urls.cancel,
		ipn_url: urls.ipn,
		cus_name: cust.name || "Customer",
		cus_email: cust.email || "noemail@example.com",
		cus_phone: cust.phone || "01700000000",
		cus_add1: "N/A",
		cus_city: "Dhaka",
		cus_country: "Bangladesh",
		shipping_method: "NO",
		product_name: "Internet / Cable TV bill",
		product_category: "Service",
		product_profile: "non-physical-goods"
	});
	const r = asObj(await (await f(`${sslBase(c.mode)}/gwprocess/v4/api.php`, {
		method: "POST",
		headers: { "Content-Type": "application/x-www-form-urlencoded" },
		body: body.toString()
	})).json());
	if (r.status !== "SUCCESS" || typeof r.GatewayPageURL !== "string") throw new Error(`SSLCommerz: ${String(r.failedreason ?? "could not start payment")}`);
	return {
		redirectUrl: r.GatewayPageURL,
		providerRef: String(r.sessionkey ?? "")
	};
}
const bkashBase = (mode) => mode === "live" ? "https://tokenized.pay.bka.sh/v1.2.0-beta" : "https://tokenized.sandbox.bka.sh/v1.2.0-beta";
async function bkashToken(f, c) {
	const r = asObj(await (await f(`${bkashBase(c.mode)}/tokenized/checkout/token/grant`, {
		method: "POST",
		headers: {
			"Content-Type": "application/json",
			Accept: "application/json",
			username: c.username,
			password: c.password
		},
		body: JSON.stringify({
			app_key: c.appKey,
			app_secret: c.appSecret
		})
	})).json());
	if (typeof r.id_token !== "string") throw new Error(`bKash: ${String(r.statusMessage ?? "token grant failed")}`);
	return r.id_token;
}
const bkashHeaders = (c, token) => ({
	"Content-Type": "application/json",
	Accept: "application/json",
	Authorization: token,
	"X-APP-Key": c.appKey
});
async function bkashCreate(f, c, txn, callbackUrl, payerRef) {
	const token = await bkashToken(f, c);
	const r = asObj(await (await f(`${bkashBase(c.mode)}/tokenized/checkout/create`, {
		method: "POST",
		headers: bkashHeaders(c, token),
		body: JSON.stringify({
			mode: "0011",
			payerReference: payerRef,
			callbackURL: callbackUrl,
			amount: Number(txn.amount).toFixed(2),
			currency: "BDT",
			intent: "sale",
			merchantInvoiceNumber: txn.id
		})
	})).json());
	if (r.statusCode !== "0000" || typeof r.bkashURL !== "string") throw new Error(`bKash: ${String(r.statusMessage ?? "could not start payment")}`);
	return {
		redirectUrl: r.bkashURL,
		providerRef: String(r.paymentID)
	};
}
const nagadBase = (mode) => mode === "live" ? "https://api.mynagad.com/api/dfs" : "http://sandbox.mynagad.com:10080/remote-payment-gateway-1.0/api/dfs";
/** Nagad order ids are short alphanumerics: derive one from the transaction uuid (and re-derive to verify). */
const nagadOrderId = (txnId) => `N${txnId.replace(/-/g, "").slice(0, 19)}`;
const pem = (k, type) => k.includes("BEGIN") ? k : `-----BEGIN ${type} KEY-----\n${k.replace(/\s+/g, "").match(/.{1,64}/g)?.join("\n")}\n-----END ${type} KEY-----`;
const nagadEncrypt = (json, pgPublicKey) => publicEncrypt({
	key: createPublicKey(pem(pgPublicKey, "PUBLIC")),
	padding: constants.RSA_PKCS1_PADDING
}, Buffer.from(json)).toString("base64");
const nagadDecrypt = (b64, merchantPrivateKey) => privateDecrypt({
	key: createPrivateKey(pem(merchantPrivateKey, "PRIVATE")),
	padding: constants.RSA_PKCS1_PADDING
}, Buffer.from(b64, "base64")).toString();
const nagadSign = (json, merchantPrivateKey) => createSign("RSA-SHA256").update(json).sign(createPrivateKey(pem(merchantPrivateKey, "PRIVATE")), "base64");
const nagadStamp = () => new Date(Date.now() + 216e5).toISOString().replace(/\D/g, "").slice(0, 14);
const nagadHeaders = (ip) => ({
	"Content-Type": "application/json",
	"X-KM-IP-V4": ip,
	"X-KM-Client-Type": "PC_WEB",
	"X-KM-Api-Version": "v-0.2.0"
});
async function nagadCreate(f, c, txn, callbackUrl, clientIp) {
	const orderId = nagadOrderId(txn.id);
	const challenge = createHash("sha256").update(`${txn.id}${Date.now()}`).digest("hex").slice(0, 40);
	const sensitive = JSON.stringify({
		merchantId: c.merchantId,
		datetime: nagadStamp(),
		orderId,
		challenge
	});
	const init = asObj(await (await f(`${nagadBase(c.mode)}/check-out/initialize/${c.merchantId}/${orderId}`, {
		method: "POST",
		headers: nagadHeaders(clientIp),
		body: JSON.stringify({
			dateTime: nagadStamp(),
			sensitiveData: nagadEncrypt(sensitive, c.pgPublicKey),
			signature: nagadSign(sensitive, c.privateKey)
		})
	})).json());
	if (typeof init.sensitiveData !== "string") throw new Error(`Nagad: ${String(init.message ?? "initialize failed")}`);
	const reply = asObj(JSON.parse(nagadDecrypt(init.sensitiveData, c.privateKey)));
	if (!reply.paymentReferenceId || !reply.challenge) throw new Error("Nagad: unexpected initialize reply");
	const order = JSON.stringify({
		merchantId: c.merchantId,
		orderId,
		currencyCode: "050",
		amount: Number(txn.amount).toFixed(2),
		challenge: String(reply.challenge)
	});
	const done = asObj(await (await f(`${nagadBase(c.mode)}/check-out/complete/${String(reply.paymentReferenceId)}`, {
		method: "POST",
		headers: nagadHeaders(clientIp),
		body: JSON.stringify({
			sensitiveData: nagadEncrypt(order, c.pgPublicKey),
			signature: nagadSign(order, c.privateKey),
			merchantCallbackURL: callbackUrl,
			additionalMerchantInfo: { txn: txn.id }
		})
	})).json());
	if (typeof done.callBackUrl !== "string") throw new Error(`Nagad: ${String(done.message ?? "could not start payment")}`);
	return {
		redirectUrl: done.callBackUrl,
		providerRef: String(reply.paymentReferenceId)
	};
}
const SECRET_NAMES = {
	sslcommerz: ["SSLCOMMERZ_STORE_ID", "SSLCOMMERZ_STORE_PASSWORD"],
	bkash: [
		"BKASH_APP_KEY",
		"BKASH_APP_SECRET",
		"BKASH_USERNAME",
		"BKASH_PASSWORD"
	],
	nagad: [
		"NAGAD_MERCHANT_ID",
		"NAGAD_MERCHANT_PRIVATE_KEY",
		"NAGAD_PG_PUBLIC_KEY"
	]
};
/** Returns the provider's config, or null when any required secret is missing (provider then counts as "not configured"). */
function loadConfig(provider, get, mode) {
	const v = Object.fromEntries(SECRET_NAMES[provider].map((n) => [n, get(n)?.trim()]));
	if (Object.values(v).some((x) => !x)) return null;
	if (provider === "sslcommerz") return {
		storeId: v.SSLCOMMERZ_STORE_ID,
		storePasswd: v.SSLCOMMERZ_STORE_PASSWORD,
		mode
	};
	if (provider === "bkash") return {
		appKey: v.BKASH_APP_KEY,
		appSecret: v.BKASH_APP_SECRET,
		username: v.BKASH_USERNAME,
		password: v.BKASH_PASSWORD,
		mode
	};
	return {
		merchantId: v.NAGAD_MERCHANT_ID,
		privateKey: v.NAGAD_MERCHANT_PRIVATE_KEY,
		pgPublicKey: v.NAGAD_PG_PUBLIC_KEY,
		mode
	};
}

// supabase/functions/payment-init/index.ts
const cors = {
	"Access-Control-Allow-Origin": "*",
	"Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
	"Access-Control-Allow-Methods": "POST, OPTIONS"
};
const json = (b, s = 200) => new Response(JSON.stringify(b), {
	status: s,
	headers: {
		...cors,
		"Content-Type": "application/json"
	}
});
const PROVIDERS = [
	"sslcommerz",
	"bkash",
	"nagad"
];
const f = (url, init) => fetch(url, init);
Deno.serve(async (req) => {
	if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
	if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);
	const url = Deno.env.get("SUPABASE_URL"), anon = Deno.env.get("SUPABASE_ANON_KEY"), service = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
	const auth = req.headers.get("Authorization") ?? "";
	if (!auth) return json({ error: "unauthorized" }, 401);
	const { data: access } = await createClient(url, anon, {
		global: { headers: { Authorization: auth } },
		auth: { persistSession: false }
	}).rpc("my_access");
	if (!access?.is_active || !access.customer_id) return json({ error: "forbidden" }, 403);
	const customerId = access.customer_id;
	const admin = createClient(url, service, { auth: { persistSession: false } });
	let body;
	try {
		body = await req.json();
	} catch {
		return json({ error: "invalid_json" }, 400);
	}
	const { data: configs } = await admin.from("integration_configs").select("provider, enabled, mode").eq("category", "payment");
	const usable = (p) => {
		const c = configs?.find((x) => x.provider === p);
		return c?.enabled && loadConfig(p, (n) => Deno.env.get(n), c.mode) ? c.mode : null;
	};
	if (body.action === "providers") return json({ providers: PROVIDERS.filter((p) => usable(p)) });
	const provider = body.provider;
	if (!PROVIDERS.includes(provider)) return json({ error: "invalid_provider" }, 400);
	const mode = usable(provider);
	if (!mode) return json({ error: "provider_not_available" }, 400);
	if (!Deno.env.get("SITE_URL")?.replace(/\/$/, "")) return json({ error: "server_not_configured: SITE_URL is not set" }, 500);
	let q = admin.from("invoices").select("id, balance_due").eq("customer_id", customerId).in("status", [
		"issued",
		"partially_paid",
		"overdue"
	]).gt("balance_due", 0);
	if (body.invoice_ids?.length) q = q.in("id", body.invoice_ids);
	const { data: invs } = await q;
	const total = Math.round((invs ?? []).reduce((s, i) => s + Number(i.balance_due), 0) * 100) / 100;
	if (!invs?.length || total <= 0) return json({ error: "nothing_to_pay" }, 400);
	if (body.invoice_ids?.length && invs.length !== new Set(body.invoice_ids).size) return json({ error: "invoice_not_payable" }, 400);
	const since = (/* @__PURE__ */ new Date(Date.now() - 6e5)).toISOString();
	const { count } = await admin.from("payment_gateway_transactions").select("id", {
		count: "exact",
		head: true
	}).eq("customer_id", customerId).gte("created_at", since);
	if ((count ?? 0) >= 10) return json({ error: "too_many_attempts" }, 429);
	const { data: txn, error: te } = await admin.from("payment_gateway_transactions").insert({
		provider,
		customer_id: customerId,
		invoice_ids: invs.map((i) => i.id),
		amount: total,
		currency: "BDT",
		mode,
		status: "initiated",
		idempotency_key: crypto.randomUUID()
	}).select("id, amount").single();
	if (te || !txn) return json({ error: te?.message ?? "could_not_create_transaction" }, 500);
	const t = {
		id: txn.id,
		amount: Number(txn.amount)
	};
	const { data: cust } = await admin.from("customers").select("full_name, email, phone").eq("id", customerId).single();
	const hook = `${url}/functions/v1/payment-webhook?provider=${provider}&txn=${t.id}`;
	try {
		const cfg = loadConfig(provider, (n) => Deno.env.get(n), mode);
		let r;
		if (provider === "sslcommerz") r = await sslInit(f, cfg, t, {
			success: `${hook}&result=success`,
			fail: `${hook}&result=fail`,
			cancel: `${hook}&result=cancel`,
			ipn: `${hook}&result=ipn`
		}, {
			name: cust?.full_name ?? "",
			email: cust?.email,
			phone: cust?.phone
		});
		else if (provider === "bkash") r = await bkashCreate(f, cfg, t, hook, customerId.slice(0, 8));
		else r = await nagadCreate(f, cfg, t, hook, req.headers.get("x-forwarded-for")?.split(",")[0].trim() ?? "127.0.0.1");
		await admin.from("payment_gateway_transactions").update({
			status: "pending",
			request_payload: { provider_ref: r.providerRef }
		}).eq("id", t.id);
		return json({
			redirect_url: r.redirectUrl,
			txn_id: t.id
		});
	} catch (e) {
		await admin.rpc("fail_gateway_payment", {
			p_txn: t.id,
			p_response: { error: e.message }
		});
		return json({ error: e.message }, 502);
	}
});
